Lemma rep_consistent : forall A m f f' x, Rep A m -> has A f -> has A f' ->
  f_a f <= x < f_a f + f_n f -> f_a f' <= x < f_a f' + f_n f' ->
  byte_of (f_v f) (x - f_a f) = byte_of (f_v f') (x - f_a f').
