  Fixpoint zws (t : Z) (k : nat) : list fct :=
    match k with O => [] | S k' => zws (t + 1) k' ++ [FCT (p0 + 12 + t * nsize) 1 0] end.

  Lemma zws_in : forall k t w, In w (zws t k) -> exists t', t <= t' < t + Z.of_nat k /\ w = FCT (p0 + 12 + t' * nsize) 1 0.
Proof using Hj Hsc.
